<?php
namespace Shakass\SideCartPro;
defined( 'ABSPATH' ) || exit;
class Shortcodes { private $cart; private $templates; public function __construct( Cart_Service $cart, Template_Loader $templates ) { $this->cart=$cart; $this->templates=$templates; } public function init(){ add_shortcode('ssc_cart_icon',array($this,'cart_icon')); add_shortcode('ssc_cart_count',array($this,'cart_count')); add_shortcode('ssc_cart_total',array($this,'cart_total')); add_shortcode('ssc_open_cart',array($this,'open_cart')); add_shortcode('ssc_cart',array($this,'cart_icon')); } public function cart_icon(){ ob_start(); $this->render_cart_icon(); return ob_get_clean(); } public function render_cart_icon(){ $html=''; ob_start(); $this->templates->render('floating-cart.php',array('count'=>$this->cart->get_count(),'total'=>$this->cart->get_total_html(),'inline'=>true)); $html=ob_get_clean(); echo apply_filters('ssc_cart_icon_html',$html); } public function cart_count(){ return esc_html((string)$this->cart->get_count()); } public function cart_total(){ return wp_kses_post($this->cart->get_total_html()); } public function open_cart($atts=array(),$content=''){ return '<button type="button" class="ssc-open-cart">'.esc_html($content?:__('Open cart','shakass-side-cart-pro')).'</button>'; } }
